import{_ as a,o as t,c as s,a3 as i}from"./chunks/framework.DQ-7HQaQ.js";const c=JSON.parse('{"title":"Optional runnable retrieval lab","description":"Run a small local source-and-retrieval example without paid APIs, then try real Ollama embeddings and generation if available.","frontmatter":{"title":"Optional runnable retrieval lab","description":"Run a small local source-and-retrieval example without paid APIs, then try real Ollama embeddings and generation if available."},"headers":[],"relativePath":"students/reference.md","filePath":"students/reference.md","lastUpdated":1794433168000}'),n={name:"students/reference.md"};function o(r,e,l,h,p,d){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="inspect-a-source-to-answer-pipeline-locally" tabindex="-1">Inspect a source-to-answer pipeline locally <a class="header-anchor" href="#inspect-a-source-to-answer-pipeline-locally" aria-label="Permalink to &quot;Inspect a source-to-answer pipeline locally&quot;">​</a></h1><p>The optional <a href="https://github.com/kaw393939/is373-rag/tree/main/student-reference" target="_blank" rel="noreferrer">student-reference folder</a> is a <strong>teaching lab</strong>, not a ready-to-submit hosted RAG application. It introduces stable source IDs, paragraph chunks, persisted SQLite FTS search, real Ollama embeddings and actual model generation.</p><h2 id="your-first-15-minutes" tabindex="-1">Your first 15 minutes <a class="header-anchor" href="#your-first-15-minutes" aria-label="Permalink to &quot;Your first 15 minutes&quot;">​</a></h2><p><strong>Goal:</strong> find a passage and explain why it answers your question. This is a suggested pace, not a timed task or submission.</p><h3 id="_1-get-the-example-about-3-minutes" tabindex="-1">1. Get the example (about 3 minutes) <a class="header-anchor" href="#_1-get-the-example-about-3-minutes" aria-label="Permalink to &quot;1. Get the example (about 3 minutes)&quot;">​</a></h3><p>You need Python 3.10+ with SQLite FTS5. No API key or model is needed. In a terminal:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/kaw393939/is373-rag.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> is373-rag</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><p>Already downloaded this repository? Open a terminal in its folder instead. Without Git, use <strong>Code → Download ZIP</strong> on GitHub, extract it, and open that folder. You should see a folder named <code>student-reference</code>.</p><h3 id="_2-import-the-five-fictional-documents-about-3-minutes" tabindex="-1">2. Import the five fictional documents (about 3 minutes) <a class="header-anchor" href="#_2-import-the-five-fictional-documents-about-3-minutes" aria-label="Permalink to &quot;2. Import the five fictional documents (about 3 minutes)&quot;">​</a></h3><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> student-reference/rag_lab.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --db</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> student-reference/lab.sqlite</span></span></code></pre></div><p>Expect five imported sources on the first run. Run it again: expect five <strong>unchanged</strong> sources rather than duplicates. The database stays on your computer.</p><h3 id="_3-ask-for-a-passage-about-4-minutes" tabindex="-1">3. Ask for a passage (about 4 minutes) <a class="header-anchor" href="#_3-ask-for-a-passage-about-4-minutes" aria-label="Permalink to &quot;3. Ask for a passage (about 4 minutes)&quot;">​</a></h3><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> student-reference/rag_lab.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> search</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --db</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> student-reference/lab.sqlite</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --question</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Who organizes events?&quot;</span></span></code></pre></div><p>Look at the returned source ID, filename and passage. Open the matching file in <code>student-reference/fixtures</code> and read it yourself. Can you point to the words that answer the question?</p><p>This output is <strong>retrieved text, not a generated answer</strong>. Keyword search is a useful baseline, not the assignment&#39;s finished vector/graph RAG implementation.</p><h3 id="_4-check-your-setup-and-explain-it-about-5-minutes" tabindex="-1">4. Check your setup and explain it (about 5 minutes) <a class="header-anchor" href="#_4-check-your-setup-and-explain-it-about-5-minutes" aria-label="Permalink to &quot;4. Check your setup and explain it (about 5 minutes)&quot;">​</a></h3><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unittest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> discover</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> student-reference</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;test_*.py&quot;</span></span></code></pre></div><p>A successful test run ends with <strong>OK</strong>. Try another question and compare the passages. Explain the path in your own words: document → chunk → search result. No extra report is required.</p><p>If <code>python3</code> is unavailable on Windows, try <code>py -3</code> in its place. If Python reports a missing file, return to the repository folder. If it reports a missing FTS5 module, use a Python installation with SQLite FTS5; do not buy an API subscription to fix an offline database problem.</p><p><strong>Next:</strong> <a href="./build">build a small complete application</a>. Keep your own topic and sources; these fictional fixtures are just practice.</p><h2 id="optional-add-a-real-model" tabindex="-1">Optional: add a real model <a class="header-anchor" href="#optional-add-a-real-model" aria-label="Permalink to &quot;Optional: add a real model&quot;">​</a></h2><p>If Ollama and compatible local models are already available, follow the <a href="https://github.com/kaw393939/is373-rag/blob/main/student-reference/README.md" target="_blank" rel="noreferrer">lab README</a> to generate <strong>real embeddings</strong> and run a model with visible evidence. Do not claim those features work on your machine until you run them.</p><h2 id="how-to-use-the-lab" tabindex="-1">How to use the lab <a class="header-anchor" href="#how-to-use-the-lab" aria-label="Permalink to &quot;How to use the lab&quot;">​</a></h2><ol><li>Predict which permitted fictional document should answer a question.</li><li>Import twice and inspect unchanged source/chunk counts.</li><li>Run lexical search and inspect its source IDs.</li><li>Compare real vector search <strong>only if</strong> your model backend is available.</li><li>Test a missing-evidence question and inspect what the model actually says.</li><li>Adapt small ideas to your existing FastAPI/server project instead of copying the whole reference as your individual app.</li></ol><p>The lab deliberately omits public authentication, user accounts, web UI, remote inference credentials and deployment. Its tests exercise local data handling, <strong>not</strong> a complete hosted system or model quality. Keep the <a href="https://github.com/kaw393939/is373-studio/blob/main/docs/projects/individual.md" target="_blank" rel="noreferrer">original assignment</a> as your checklist.</p><p><a href="./build">Read the build steps</a> · <a href="./prompts">Try the agent prompts</a></p>`,26)])])}const m=a(n,[["render",o]]);export{c as __pageData,m as default};
